def minPiecesPowersOfFive(s):
    n = len(s)
    words = []
    x = 1
    while x.bit_length() <= n:
        words.append(bin(x)[2:])
        x *= 5
    INF = n + 1
    dp = [INF] * (n + 1)
    dp[0] = 0
    for i in range(n):
        if dp[i] == INF or s[i] == '0':
            continue
        for w in words:
            j = i + len(w)
            if j > n:
                break
            if dp[i] + 1 < dp[j] and s.startswith(w, i):
                dp[j] = dp[i] + 1
    return dp[n] if dp[n] < INF else -1
